-- Tabelas combinadas enviadas pelas transportadoras (filial Campo Grande).
-- Rodar no SQL Editor do projeto de CAMPO GRANDE, depois do RODAR_TUDO_fretes.sql.
-- Apaga e recria só as tabelas destas 3 transportadoras (pode rodar de novo).
delete from public.frete_tabelas where filial = 'CGR' and transportadora in ('PANTANAL TRANSPORTES','VIATUR','LH TRANSPORTES');
